import { AgGridData } from 'components/Table/types';

import { hasTableBreakdownData } from './hasTableBreakdownData';

export const hasOverviewTableData = (tableData?: AgGridData): boolean => {
  if (!tableData || typeof tableData !== 'object') {
    return false;
  }

  return Object.values(tableData).some(
    (table) =>
      table && typeof table === 'object' && hasTableBreakdownData(table),
  );
};
